// Stages everything the Tauri bundle carries for the sidecar (plan 11-01, D-192):
//   binaries/flywheel-node-<triple>     a checksum-verified official Node runtime
//   binaries/flywheel-shim-<triple>     the workspace's flywheel-shim, release build
//   binaries/flywheel-sidecar-<triple>  launcher.sh (see its header)
//   resources/sidecar/                  dist/ + production node_modules
// All of it is a build output: gitignored, regenerated by `npm run build:dist`.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

// STACK.md "Node.js (bundled sidecar runtime)": a pinned Node 22 LTS. Bump deliberately.
const NODE_VERSION = "22.23.3";

const here = path.dirname(fileURLToPath(import.meta.url));
const sidecarDir = path.resolve(here, "..");
const repoRoot = path.resolve(sidecarDir, "..", "..");
const tauriDir = path.join(repoRoot, "packages", "desktop", "src-tauri");
const binariesDir = path.join(tauriDir, "binaries");
const resourcesDir = path.join(tauriDir, "resources", "sidecar");
const cacheDir = path.join(sidecarDir, ".runtime-cache");

// Rust target triple -> nodejs.org platform string. Extend when a new target is actually shipped.
const NODE_PLATFORM = {
  "aarch64-apple-darwin": "darwin-arm64",
  "x86_64-apple-darwin": "darwin-x64",
};

function run(cmd, args, opts = {}) {
  return execFileSync(cmd, args, { stdio: "inherit", ...opts });
}

function hostTriple() {
  let out;
  try {
    out = execFileSync("rustc", ["-vV"], { encoding: "utf8" });
  } catch (err) {
    throw new Error(`stage-runtime: rustc is required to resolve the target triple: ${err.message}`);
  }
  const m = /^host:\s*(\S+)$/m.exec(out);
  if (!m) throw new Error("stage-runtime: no `host:` line in `rustc -vV` output");
  return m[1];
}

const sha256 = (file) => createHash("sha256").update(fs.readFileSync(file)).digest("hex");

async function download(url, dest) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`stage-runtime: GET ${url} -> ${res.status}`);
  fs.writeFileSync(dest, Buffer.from(await res.arrayBuffer()));
}

/** T-11-01: the tarball is only ever used after it matches nodejs.org's own SHASUMS256.txt. A
 * mismatching cache entry is deleted and re-fetched once; a second mismatch is fatal. */
async function verifiedNodeTarball(platform) {
  const base = `https://nodejs.org/dist/v${NODE_VERSION}`;
  const name = `node-v${NODE_VERSION}-${platform}.tar.gz`;
  fs.mkdirSync(cacheDir, { recursive: true });
  const sums = path.join(cacheDir, `SHASUMS256-v${NODE_VERSION}.txt`);
  if (!fs.existsSync(sums)) await download(`${base}/SHASUMS256.txt`, sums);
  const line = fs.readFileSync(sums, "utf8").split("\n").find((l) => l.endsWith(`  ${name}`));
  if (!line) throw new Error(`stage-runtime: ${name} is not listed in SHASUMS256.txt`);
  const expected = line.split(/\s+/)[0];

  const tarball = path.join(cacheDir, name);
  for (let attempt = 0; attempt < 2; attempt++) {
    if (!fs.existsSync(tarball)) await download(`${base}/${name}`, tarball);
    if (sha256(tarball) === expected) return tarball;
    fs.rmSync(tarball, { force: true });
  }
  throw new Error(`stage-runtime: ${name} does not match SHASUMS256.txt after a re-download; refusing to use it`);
}

function install(src, dest) {
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(src, dest);
  fs.chmodSync(dest, 0o755);
}

const triple = hostTriple();
const platform = NODE_PLATFORM[triple];
if (!platform) throw new Error(`stage-runtime: no Node platform mapping for target ${triple}`);

// 1-3. Node runtime.
const tarball = await verifiedNodeTarball(platform);
const extractDir = path.join(cacheDir, `extract-${NODE_VERSION}-${platform}`);
fs.rmSync(extractDir, { recursive: true, force: true });
fs.mkdirSync(extractDir, { recursive: true });
run("tar", ["-xzf", tarball, "-C", extractDir]);
install(path.join(extractDir, `node-v${NODE_VERSION}-${platform}`, "bin", "node"), path.join(binariesDir, `flywheel-node-${triple}`));
fs.rmSync(extractDir, { recursive: true, force: true });

// 4. Shim.
run("cargo", ["build", "-p", "flywheel-shim", "--release"], { cwd: repoRoot });
install(path.join(repoRoot, "target", "release", "flywheel-shim"), path.join(binariesDir, `flywheel-shim-${triple}`));

// 5. Sidecar payload: dist/ plus production-only dependencies from a clean prefix (T-11-03).
fs.rmSync(resourcesDir, { recursive: true, force: true });
fs.mkdirSync(resourcesDir, { recursive: true });
for (const f of ["package.json", "package-lock.json"]) fs.copyFileSync(path.join(sidecarDir, f), path.join(resourcesDir, f));
run("npm", ["ci", "--omit=dev", "--ignore-scripts", "--no-audit", "--no-fund"], { cwd: resourcesDir });
fs.cpSync(path.join(sidecarDir, "dist"), path.join(resourcesDir, "dist"), { recursive: true });

// 6. Launcher.
install(path.join(here, "launcher.sh"), path.join(binariesDir, `flywheel-sidecar-${triple}`));

console.log(`stage-runtime: staged node ${NODE_VERSION}, shim, launcher and resources for ${triple}`);
